import{_ as r,g as a,e as t,a4 as n}from"./chunks/framework.CEYJDsBW.js";const p=JSON.parse('{"title":"dev.dubhe.anvilcraft.integration.jei.transfer","description":"","frontmatter":{},"headers":[],"relativePath":"anvilcraft/21.1/api/dev-dubhe-anvilcraft-integration-jei-transfer.md","filePath":"anvilcraft/21.1/api/dev-dubhe-anvilcraft-integration-jei-transfer.md"}'),i={name:"anvilcraft/21.1/api/dev-dubhe-anvilcraft-integration-jei-transfer.md"};function c(l,e,d,o,b,s){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="dev-dubhe-anvilcraft-integration-jei-transfer" tabindex="-1">dev.dubhe.anvilcraft.integration.jei.transfer <a class="header-anchor" href="#dev-dubhe-anvilcraft-integration-jei-transfer" aria-label="Permalink to &quot;dev.dubhe.anvilcraft.integration.jei.transfer&quot;">​</a></h1><h2 id="irecipetransfercallable" tabindex="-1">IRecipeTransferCallable <a class="header-anchor" href="#irecipetransfercallable" aria-label="Permalink to &quot;IRecipeTransferCallable&quot;">​</a></h2><p><code>public interface IRecipeTransferCallable</code></p><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/integration/jei/transfer/IRecipeTransferCallable.java#L12" target="_blank" rel="noreferrer">类型声明</a></p><p>重试原 Handler 传输逻辑的调用入口。各模组 Handler 的 mixin 通过 lambda 传入 &quot;调用被注入的 transferRecipe 原方法&quot;，使 TerminalJeiTransferSupport 与具体 Handler 类解耦。</p><p>类型注解 <code>@FunctionalInterface</code></p><table tabindex="0"><thead><tr><th>成员签名</th><th>实现与调用约定</th><th>源码</th></tr></thead><tbody><tr><td><code>@Nullable IRecipeTransferError transfer()</code></td><td>调用原 Handler 的传输方法（doTransfer=true）。<br>返回 原方法的传输错误；null 表示成功</td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/integration/jei/transfer/IRecipeTransferCallable.java#L19" target="_blank" rel="noreferrer">方法</a></td></tr></tbody></table><h2 id="smithingrecipetransferhandler" tabindex="-1">SmithingRecipeTransferHandler <a class="header-anchor" href="#smithingrecipetransferhandler" aria-label="Permalink to &quot;SmithingRecipeTransferHandler&quot;">​</a></h2><p><code>public final class SmithingRecipeTransferHandler&lt;C extends AbstractContainerMenu, R&gt; implements IRecipeTransferHandler&lt;C, R&gt;</code></p><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/integration/jei/transfer/SmithingRecipeTransferHandler.java#L35" target="_blank" rel="noreferrer">类型声明</a></p><table tabindex="0"><thead><tr><th>成员签名</th><th>实现与调用约定</th><th>源码</th></tr></thead><tbody><tr><td><code>public static void register(IRecipeTransferRegistration registration)</code></td><td>实现调用 <code>ModMenuTypes.ROYAL_SMITHING.get()</code><br>实现调用 <code>ModMenuTypes.EMBER_SMITHING.get()</code><br>实现调用 <code>ModMenuTypes.FROST_SMITHING.get()</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/integration/jei/AnvilCraftJeiPlugin.java#L355" target="_blank" rel="noreferrer">调用处 AnvilCraftJeiPlugin.registerRecipeTransferHandlers</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/integration/jei/transfer/SmithingRecipeTransferHandler.java#L67" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public Class&lt;? extends C&gt; getContainerClass()</code></td><td>末尾返回 <code>this.materials.getContainerClass()</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/integration/jei/transfer/SmithingRecipeTransferHandler.java#L100" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public Optional&lt;MenuType&lt;C&gt;&gt; getMenuType()</code></td><td>末尾返回 <code>this.materials.getMenuType()</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/integration/jei/transfer/SmithingRecipeTransferHandler.java#L105" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public RecipeType&lt;R&gt; getRecipeType()</code></td><td>末尾返回 <code>this.materials.getRecipeType()</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/integration/jei/transfer/SmithingRecipeTransferHandler.java#L110" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override @Nullable public IRecipeTransferError transferRecipe( C menu, R recipe, IRecipeSlotsView slots, Player player, boolean maxTransfer, boolean doTransfer )</code></td><td><code>(templateViews.isEmpty())</code> 成立时提前返回 <code>this.helper.createInternalError()</code><br><code>(error != null || !doTransfer)</code> 成立时提前返回 <code>error</code><br><code>(ItemStack.isSameItemSameComponents(selectedTemplate(menu), template))</code> 成立时提前返回 <code>this.materials.transferRecipe(menu, recipe, materialViews, player, maxTransfer, true)</code><br>末尾返回 <code>null</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/integration/jei/transfer/SmithingRecipeTransferHandler.java#L115" target="_blank" rel="noreferrer">方法</a></td></tr></tbody></table><h2 id="structurescannerrecipetransferhandler" tabindex="-1">StructureScannerRecipeTransferHandler <a class="header-anchor" href="#structurescannerrecipetransferhandler" aria-label="Permalink to &quot;StructureScannerRecipeTransferHandler&quot;">​</a></h2><p><code>public final class StructureScannerRecipeTransferHandler&lt;R extends RecipeHolder&lt;?&gt;&gt; implements IRecipeTransferHandler&lt;StructureScannerMenu, R&gt;</code></p><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/integration/jei/transfer/StructureScannerRecipeTransferHandler.java#L20" target="_blank" rel="noreferrer">类型声明</a></p><table tabindex="0"><thead><tr><th>成员签名</th><th>实现与调用约定</th><th>源码</th></tr></thead><tbody><tr><td><code>public static void register(IRecipeTransferRegistration registration)</code></td><td>实现调用 <code>registration.getTransferHelper()</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/integration/jei/AnvilCraftJeiPlugin.java#L356" target="_blank" rel="noreferrer">调用处 AnvilCraftJeiPlugin.registerRecipeTransferHandlers</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/integration/jei/transfer/StructureScannerRecipeTransferHandler.java#L30" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public Class&lt;? extends StructureScannerMenu&gt; getContainerClass()</code></td><td>末尾返回 <code>StructureScannerMenu.class</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/integration/jei/transfer/StructureScannerRecipeTransferHandler.java#L37" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public Optional&lt;MenuType&lt;StructureScannerMenu&gt;&gt; getMenuType()</code></td><td>末尾返回 <code>Optional.of(ModMenuTypes.STRUCTURE_SCANNER.get())</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/integration/jei/transfer/StructureScannerRecipeTransferHandler.java#L42" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override public RecipeType&lt;R&gt; getRecipeType()</code></td><td>末尾返回 <code>this.type</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/integration/jei/transfer/StructureScannerRecipeTransferHandler.java#L47" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>@Override @Nullable public IRecipeTransferError transferRecipe( StructureScannerMenu menu, R recipe, IRecipeSlotsView slots, Player player, boolean maxTransfer, boolean doTransfer )</code></td><td><code>(!menu.stillValid(player) || BlueprintClientFiles.isBusy())</code> 成立时提前返回 <code>this.helper.createInternalError()</code><br>末尾返回 <code>null</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/integration/jei/transfer/StructureScannerRecipeTransferHandler.java#L52" target="_blank" rel="noreferrer">方法</a></td></tr></tbody></table><h2 id="terminaljeitransfersupport" tabindex="-1">TerminalJeiTransferSupport <a class="header-anchor" href="#terminaljeitransfersupport" aria-label="Permalink to &quot;TerminalJeiTransferSupport&quot;">​</a></h2><p><code>public final class TerminalJeiTransferSupport</code></p><p><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/integration/jei/transfer/TerminalJeiTransferSupport.java#L48" target="_blank" rel="noreferrer">类型声明</a></p><p>终端支持的 JEI 配方转移补全逻辑（与具体 Handler 解耦）： #checkSatisfies：检查阶段（doTransfer=false）——汇总玩家绑定终端的存储 物品数量，结合背包已有量计算每个配方槽的实际缺口；无缺口返回 null（&quot;+&quot; 可用）， 有缺口返回精确的缺失错误（每个缺失槽只高亮一次）。 #restockThenTransfer：传输阶段（doTransfer=true）——按配方各槽位实际上限 计算背包缺口，先从存储站补足（异步），补库完成后通过 IRecipeTransferCallable 重试原传输逻辑；重试后统计背包中本次补入物品的剩余量（JEI 转移失败或部分使用时 剩余），把多余材料退回存储站，避免残留在玩家背包。 匹配语义与 JEI 自身一致（RecipeTransferUtil.calculateRequiredCountsByUid）： 配方输入槽是一组可替换的变体，槽内任意变体都满足该槽；同一物品用 IStackHelper#getUidForStack 的 uid 判定相等（含 subtype），tag 原料（如 #minecraft:planks）展开的所有变体即所有木板。 不注入 getInventoryState：其声明的&quot;虚拟空槽&quot;无法让服务端实际取到物品。</p><table tabindex="0"><thead><tr><th>成员签名</th><th>实现与调用约定</th><th>源码</th></tr></thead><tbody><tr><td><code>public static @Nullable IRecipeTransferError checkSatisfies( AbstractContainerMenu container, IRecipeSlotsView recipeSlots, Player player, IStackHelper stackHelper, IRecipeTransferHandlerHelper helper )</code></td><td>检查阶段：结合「背包 + 合成格」与「全部绑定终端存储」计算配方缺口。<br>参数 <code>stackHelper</code> JEI 的 uid 工具（判定配方变体与背包/存储物品是否同一物品）<br>参数 <code>helper</code> JEI 传输错误工厂（用于构造精确缺失错误）<br>返回 null 表示&quot;+&quot;可用（存储可补足，或缓存未就绪时的乐观判定——点击后由 补库 + 重试给出真实结果）；否则返回缺失错误（只高亮真正缺的槽）<br>末尾返回 <code>TerminalJeiTransferSupport.checkSatisfies( container.slots, container.getCarried(), recipeSlots, player, stackHelper, helper )</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/integration/jei/transfer/TerminalJeiTransferSupport.java#L60" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static @Nullable IRecipeTransferError checkSatisfies( List&lt;Slot&gt; slots, IRecipeSlotsView recipeSlots, Player player, IStackHelper stackHelper, IRecipeTransferHandlerHelper helper )</code></td><td>使用 Handler 的实际配方与物品栏槽，兼容不在菜单 slots 中的升级合成格。<br>末尾返回 <code>TerminalJeiTransferSupport.checkSatisfies(slots, ItemStack.EMPTY, recipeSlots, player, stackHelper, helper)</code></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/integration/jei/transfer/TerminalJeiTransferSupport.java#L73" target="_blank" rel="noreferrer">方法</a></td></tr><tr><td><code>public static boolean restockThenTransfer( AbstractContainerMenu container, List&lt;Slot&gt; craftingSlots, List&lt;Slot&gt; inventorySlots, IRecipeSlotsView recipeSlots, Player player, IStackHelper stackHelper, boolean maxTransfer, IRecipeTransferCallable transfer )</code></td><td>传输阶段：补足背包缺口后重试原传输逻辑；重试后把本次补入但未使用的材料退回存储站。<br>参数 <code>craftingSlots</code> 配方槽（与 recipeSlots 的 INPUT 视图按索引对应）<br>参数 <code>inventorySlots</code> JEI 转移使用的物品栏槽（补库/退回的统计范围）<br>参数 <code>stackHelper</code> JEI 的 uid 工具（判定配方变体与背包/存储物品是否同一物品）<br>参数 <code>transfer</code> 原 Handler 的传输方法（重试调用，内部应跳过本支持类的再次编排）<br>返回 true 表示本次转移已被本方法拦截（补库进行中，稍后重试原逻辑）， 调用方应返回成功（null）并停止原方法；false 表示无需补库， 调用方应继续执行原传输逻辑<br><code>(storageIds.isEmpty())</code> 成立时提前返回 <code>false</code><br><code>(missing.isEmpty())</code> 成立时提前返回 <code>false</code><br>末尾返回 <code>true</code><br><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/mixin/JeiBasicRecipeTransferHandlerMixin.java#L106" target="_blank" rel="noreferrer">调用处 JeiBasicRecipeTransferHandlerMixin.anvilcraft$restockOrAllow</a></td><td><a href="https://github.com/Anvil-Dev/AnvilCraft/blob/6a4cde43b4ece65b765137a7aab145b9b4c002bf/src/main/java/dev/dubhe/anvilcraft/integration/jei/transfer/TerminalJeiTransferSupport.java#L122" target="_blank" rel="noreferrer">方法</a></td></tr></tbody></table>',20)])])}const h=r(i,[["render",c]]);export{p as __pageData,h as default};
